<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Barcode management</h2><p class="text-muted">Generate printable Code 128 labels from each book ISBN.</p></div></div><div class="row g-3"><?php foreach($books as $b):?><div class="col-md-4"><div class="card p-3"><h5><?= Security::e($b['title']) ?></h5><p class="text-muted mb-2"><?= Security::e($b['isbn']) ?></p><svg id="barcode<?= $b['id'] ?>"></svg><button class="btn btn-sm btn-pink mt-2" onclick="window.print()">Print label</button></div></div><?php endforeach;?></div><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script><?php foreach($books as $b):?>JsBarcode('#barcode<?= $b['id'] ?>','<?= Security::e($b['isbn']) ?>',{format:'CODE128',width:2,height:45,displayValue:true,lineColor:'#20252b'});<?php endforeach;?></script><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
